const result = $input.first()?.json?.result || {};
const pipelines = result.pipelines || [];
const stageCount = result.stage_count || 0;
const batchId = 'velocity-' + new Date().toISOString().slice(0, 10) + '-' + Date.now();
const now = new Date().toISOString();
const runSql = "INSERT INTO report_sync_runs (workflow_name, source_system, report_date, batch_id, status, started_at, finished_at, row_count, error_count, retry_count, cursor_value, error_message, metadata) " + "VALUES ('LT - Report Pipeline Velocity', 'ghl', CURRENT_DATE, '" + batchId + "', 'completed', '" + now + "', '" + now + "', " + stageCount + ", 0, 0, CURRENT_DATE::text, NULL, " + "jsonb_build_object('workflow', 'LT - Report Pipeline Velocity', 'pipelines', '" + JSON.stringify(pipelines).replace(/'/g, "''") + "'))";
const wmSql = "INSERT INTO report_sync_watermarks (workflow_name, source_system, watermark_key, watermark_value, updated_at) " + "VALUES ('LT - Report Pipeline Velocity', 'ghl', 'last_velocity_compute', CURRENT_DATE::text, NOW()) " + "ON CONFLICT (workflow_name, source_system, watermark_key) DO UPDATE SET watermark_value = EXCLUDED.watermark_value, updated_at = NOW()";
const hlSql = "INSERT INTO report_source_health (source_system, status, last_success_at, last_attempt_at, last_row_count, stale_after_hours, last_error, metadata, updated_at) " + "VALUES ('velocity', 'ready', '" + now + "', '" + now + "', " + stageCount + ", 48, NULL, " + "jsonb_build_object('workflow', 'LT - Report Pipeline Velocity'), NOW()) " + "ON CONFLICT (source_system) DO UPDATE SET status = EXCLUDED.status, last_success_at = EXCLUDED.last_success_at, last_attempt_at = EXCLUDED.last_attempt_at, last_row_count = EXCLUDED.last_row_count, metadata = EXCLUDED.metadata, updated_at = NOW()";
return [{ json: { sql: runSql + ';' + wmSql + ';' + hlSql } }];

